const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const catalog=[['writing','毕业论文','论文与报告'],['proposal','开题报告','论文与报告'],['summary','文献综述','论文与报告'],['taskbook','任务书','论文与报告'],['article','期刊文章','论文与报告'],['course','课程作业','论文与报告'],['practice','实践报告','论文与报告'],['idea','课题思路','研究准备'],['questionnaire','问卷设计','研究准备'],['analysis','数据分析','研究准备'],['quick','快速写作','研究准备']];
const descriptions={
 '毕业论文':'完整论文结构与章节写作',
 '开题报告':'研究背景、目标与方法梳理',
 '文献综述':'归纳文献脉络与研究空白',
 '任务书':'拆解研究任务与时间计划',
 '期刊文章':'面向投稿的文章结构整理',
 '课程作业':'按课程要求完成研究作业',
 '实践报告':'整理实践过程与成果反思',
 '课题思路':'从问题出发形成研究计划',
 '问卷设计':'设计问题、维度与答题说明',
 '数据分析':'整理变量、样本与分析计划',
 '快速写作':'快速生成可编辑的写作框架'
};
export function catalogNav(id){return `<section id="writing-capabilities" class="writing-catalog writing-capabilities" aria-label="全部写作能力"><div class="capabilities-head"><div><span class="capabilities-kicker">STEP 01 · START HERE</span><h2>全部写作能力</h2><p>围绕论文写作与研究准备，选择适合当前阶段的任务。</p></div><span class="capabilities-count">${catalog.length} 项能力</span></div><div class="writing-recommendation"><div class="writing-recommendation-copy"><span>推荐流程 · 毕业论文</span><h3>从题目与资料开始，逐步建立你的论文草稿</h3><p>基础信息、资料补充、文献确认、提纲确认和版本预览都在同一条流程里。</p></div><div class="writing-recommendation-meta"><span><b>5</b> 个步骤</span><span><b>可</b> 保存返回</span><span><b>可</b> 编辑导出</span></div><a class="btn primary writing-recommendation-cta" href="#tool/writing">立即开始 <span aria-hidden="true">→</span></a></div><div class="capability-groups">${['论文与报告','研究准备'].map((group,gi)=>`<div class="capability-group"><div class="capability-group-title"><span class="capability-group-icon">${gi===0?'▤':'✦'}</span><div><strong>${group}</strong><small>${gi===0?'从研究信息到成果交付':'从问题与材料开始规划研究'}</small></div></div><div class="capability-list">${catalog.filter(t=>t[2]===group).map(([key,label],i)=>{const selected=id==='writing'?key==='writing':key===id;return `<a class="capability-card" href="#tool/${key}" ${selected?'aria-current="page"':''}><span class="capability-index">${String(i+1).padStart(2,'0')}</span><span class="capability-copy"><strong>${label}${selected&&id==='writing'?'<em>推荐</em>':''}</strong><small>${descriptions[label]||'按步骤完成研究写作'}</small></span><span class="capability-arrow" aria-hidden="true">→</span></a>`;}).join('')}</div></div>`).join('')}</div></section>`;}
const common=[['填写研究信息','填写题目、学段和研究要求；目标字数是规划值，不会自动补齐内容。'],['核对文献与材料','导入有权使用的材料，核对解析正文。当前不自动检索文献，也不会将材料用于 AI 生成。'],['确认结构','生成本地模板，调整章节和顺序；示例不是生成结果。'],['编辑并保存','根据真实研究填写正文，保存草稿；切换任务前保存或导出。'],['导出与核对','导出当前已填写内容，再核对事实、引用及学校格式。']];
const specific={questionnaire:[['填写研究目标','说明主题、目标人群及维度。'],['编辑问卷草稿','填写问题、选项与答题说明；先进行小范围试填。'],['导出问卷','当前提供本地草稿，在线发布、二维码与答卷回收尚未接入。']],analysis:[['填写分析计划','记录研究问题、变量、数据来源和预期方法。'],['准备真实数据','说明缺失值、样本与变量类型；不能把计划当成计算结果。'],['保存分析计划','当前保存与导出计划，不执行统计检验或输出分析数值。']],practice:[['记录真实经历','填写单位、岗位、时间及实际工作内容。'],['整理报告','在框架中补充过程、发现与反思，不编造实践经历。'],['保存与导出','保存草稿，逐项核对单位、日期和成果。']],idea:[['明确研究问题','输入专业、兴趣、研究问题和可获得的数据。'],['讨论研究可行性','核对研究范围、方法与资料来源。'],['保存计划','当前生成整理框架，不替代真实文献检索。']]};
export function guideMarkup(id){const item=catalog.find(t=>t[0]===id)||(id==='topic'?catalog.find(t=>t[0]==='idea'):null),name=item?.[1]||'写作任务',steps=specific[id]||(id==='topic'?specific.idea:null)||common;return `<section class="writing-guide-shell"><div class="writing-guide-top"><div><span class="capabilities-kicker">STEP 02 · YOUR WORKFLOW</span><h2>${escape(name)}的完成路径</h2><p>每一步都可以保存和返回，先核对输入，再开始下一步。</p></div><button class="btn secondary guide-toggle" type="button" aria-expanded="true" aria-controls="writing-guide">收起步骤</button></div><section id="writing-guide" class="writing-guide" aria-label="${escape(name)}操作指南"><ol>${steps.map(([title,desc],i)=>`<li><span>${i+1}</span><div><b>${title}</b><p>${desc}</p></div></li>`).join('')}</ol><p class="guide-boundary">本地数据保存在当前浏览器，请及时导出。模型、在线检索、发布与收费状态以页面说明为准。</p></section></section>`;}
export function bindGuide(){const button=document.querySelector('.guide-toggle'),panel=document.querySelector('#writing-guide');if(!button||!panel)return;let open=true;try{open=localStorage.getItem('paperknow-writing-guide')!=='hidden';}catch{}const apply=()=>{panel.hidden=!open;button.setAttribute('aria-expanded',String(open));button.textContent=open?'隐藏操作指南':'操作指南';};apply();button.onclick=()=>{open=!open;apply();try{localStorage.setItem('paperknow-writing-guide',open?'visible':'hidden');}catch{}};}

export const writingHeading=()=>`<section class="writing-hero"><div class="writing-hero-copy"><span class="overline">PAPERKNOW · AI WRITING</span><h1>让研究思路，形成清晰的论文草稿</h1><p>从基础信息、材料与文献，到提纲确认、正文编辑，分步推进写作。</p><div class="writing-hero-proof"><span><i>✓</i> 5 步流程</span><span><i>✓</i> 支持保存返回</span><span><i>✓</i> 内容可编辑</span></div><div class="writing-hero-actions"><a class="btn primary" href="#tool/writing">开始毕业论文 <span aria-hidden="true">→</span></a><button class="btn secondary writing-hero-secondary" type="button" data-scroll-to="writing-capabilities">查看其他能力 <span aria-hidden="true">↓</span></button></div></div><div class="writing-hero-side"><div class="writing-hero-side-top"><span>推荐流程</span><b>本地草稿</b></div><strong>毕业论文</strong><p>从基础信息到版本确认</p><ol class="writing-hero-mini-steps"><li class="is-active"><span>1</span><b>基础信息</b></li><li><span>2</span><b>精准补充</b></li><li><span>3</span><b>文献确认</b></li><li><span>4</span><b>提纲确认</b></li><li><span>5</span><b>版本确认</b></li></ol><div class="writing-hero-side-footer"><span>✓ 支持保存返回</span><span>↗ 确认后导出</span></div><a class="writing-history-link" href="#assets">查看我的写作记录 <span aria-hidden="true">→</span></a></div></section>`;
export const writingDetailHeading=id=>{const item=catalog.find(t=>t[0]===id)||(id==='topic'?catalog.find(t=>t[0]==='idea'):null)||catalog[0];return `<section class="writing-detail-heading"><a class="writing-back-link" href="#category/writing">← 返回 AI 写作</a><div><span class="capabilities-kicker">PAPERKNOW · AI WRITING</span><h1>${escape(item[1])}</h1><p>${escape(descriptions[item[1]]||'按步骤完成研究写作')}</p></div><span class="writing-detail-badge">写作工作区</span></section>`;};
export function retainWritingCatalog(previous,current,focused=previous?.contains(document.activeElement)?document.activeElement:null){if(!previous||!current)return;const selected=current.querySelector('[aria-current="page"]')?.getAttribute('href');for(const link of previous.querySelectorAll('a')){if(link.getAttribute('href')===selected)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}current.replaceWith(previous);focused?.focus({preventScroll:true});}
